-- Vorschlag: separate Datenhaltung für das neue Tool, NICHT auf bestehender Produktions-DB ausführen.
PRAGMA foreign_keys = ON;
CREATE TABLE nu_company(id TEXT PRIMARY KEY, name TEXT NOT NULL, owner TEXT NOT NULL DEFAULT '', country TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', default_rate_cents INTEGER CHECK(default_rate_cents>=0));
CREATE TABLE nu_company_alias(alias TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES nu_company(id));
CREATE TABLE nu_team(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES nu_company(id), name TEXT NOT NULL, UNIQUE(company_id,name));
CREATE TABLE nu_project_agreement(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES nu_company(id),project_id TEXT,project_label TEXT NOT NULL,fitter_rate_cents INTEGER,foreman_rate_cents INTEGER,net_days INTEGER,discount_enabled INTEGER NOT NULL DEFAULT 0,discount_days INTEGER,discount_basis_points INTEGER,version INTEGER NOT NULL DEFAULT 1,UNIQUE(company_id,project_label));
CREATE TABLE nu_worker(id TEXT PRIMARY KEY,team_id TEXT REFERENCES nu_team(id), assessment_json TEXT NOT NULL DEFAULT '{}', company_id TEXT NOT NULL REFERENCES nu_company(id), placeholder TEXT NOT NULL, name TEXT, role TEXT NOT NULL DEFAULT 'Monteur', rating INTEGER CHECK(rating BETWEEN 1 AND 10), default_rate_cents INTEGER CHECK(default_rate_cents>=0));
CREATE TABLE nu_assignment(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, company_id TEXT NOT NULL REFERENCES nu_company(id), worker_id TEXT NOT NULL REFERENCES nu_worker(id), iso_week TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(project_id,worker_id,iso_week));
CREATE TABLE nu_day(id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL REFERENCES nu_assignment(id) ON DELETE CASCADE, day TEXT NOT NULL, minutes INTEGER NOT NULL CHECK(minutes>=0 AND minutes<=1440 AND minutes%1=0), rate_cents INTEGER NOT NULL CHECK(rate_cents>=0), UNIQUE(assignment_id,day));
CREATE TABLE nu_confirmation(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, company_id TEXT NOT NULL REFERENCES nu_company(id), iso_week TEXT NOT NULL, snapshot_json TEXT NOT NULL, confirmed_by TEXT NOT NULL, confirmed_at TEXT NOT NULL, revision INTEGER NOT NULL, revoked_at TEXT, UNIQUE(project_id,company_id,iso_week,revision));
CREATE TABLE nu_document(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES nu_company(id), worker_id TEXT REFERENCES nu_worker(id), kind TEXT NOT NULL, filename TEXT NOT NULL, storage_key TEXT NOT NULL, project_agreement_id TEXT REFERENCES nu_project_agreement(id),valid_until TEXT, expiry_confirmed_by TEXT, expiry_confirmed_at TEXT, uploaded_at TEXT NOT NULL);
CREATE INDEX nu_doc_expiry ON nu_document(valid_until);
CREATE INDEX nu_project_week ON nu_assignment(project_id,iso_week);
CREATE TABLE nu_week_adjustment(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,company_id TEXT NOT NULL REFERENCES nu_company(id),iso_week TEXT NOT NULL,adjustment_minutes INTEGER NOT NULL CHECK(adjustment_minutes%1=0),rate_cents INTEGER NOT NULL CHECK(rate_cents>=0),reason TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,UNIQUE(project_id,company_id,iso_week));

CREATE TABLE nu_invoice_review(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES nu_company(id),project_id TEXT NOT NULL,iso_week TEXT NOT NULL,invoice_number TEXT,file_hash TEXT NOT NULL,storage_key TEXT NOT NULL,expected_cents INTEGER NOT NULL,net_cents INTEGER NOT NULL,gross_cents INTEGER NOT NULL,retention_cents INTEGER NOT NULL DEFAULT 0,discount_cents INTEGER NOT NULL DEFAULT 0,payment_cents INTEGER NOT NULL,payment_date TEXT NOT NULL,paid INTEGER NOT NULL DEFAULT 0,reviewer TEXT NOT NULL,reviewed_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,needs_recheck INTEGER NOT NULL DEFAULT 0,details_json TEXT NOT NULL,UNIQUE(company_id,invoice_number),UNIQUE(company_id,file_hash),UNIQUE(company_id,project_id,iso_week));

-- Nur Vorschlag für separate neue Tool-Datenhaltung, nicht auf Quelle ausführen.
CREATE TABLE nu_retention_release(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES nu_company(id),project_id TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(amount_cents>0),status TEXT NOT NULL CHECK(status IN ('prepared','paid','cancelled')),planned_date TEXT NOT NULL,paid_date TEXT,reviewer TEXT NOT NULL,acceptance_date TEXT,created_at TEXT NOT NULL,paid_at TEXT,cancelled_at TEXT,snapshot_json TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
-- Auszahlung atomar gegen verfügbaren Saldo prüfen, inklusive anderer Reservierungen.
